export function getLineBreakClass(codePoint: number): number {
  let index = codePoint
  if (codePoint >= 0x80) {
    const block = codePoint >> 7
    if (block >= 2048) {
      return codePoint === 0xE0001 ? 8 :
      codePoint >= 0xE0020 && codePoint <= 0xE007F ? 8 :
      codePoint >= 0xE0100 && codePoint <= 0xE01EF ? 8 :
      0
    }
    const ids = stage1
    const id = ((ids.charCodeAt(block << 1) - 0x23) << 5) | (ids.charCodeAt((block << 1) + 1) - 0x23)
    index = (id << 7) | (codePoint & 0x7F)
  }
  return stage2.charCodeAt(index) - 0x23
}
